    """
    From the current New Product page (Name and SKU already set):
    - open Prices and set Price to 169.99
    - open Inventory and set Qty to 42 and mark In Stock
    - set Size = 34 and Color = Blue if those attribute controls are present
    - click Save (final action)
    """
    import asyncio

    # Ensure page UI is ready
    try:
        await page.wait_for_load_state("networkidle")
    except Exception:
        await asyncio.sleep(1)

    # 1) Open Prices panel so Price input is visible
    try:
        await page.get_by_role("link", name="Prices").click()
        try:
            await page.wait_for_load_state("networkidle")
        except Exception:
            await asyncio.sleep(0.5)
    except Exception:
        # If not interactable or already active, continue
        pass

    # 2) Fill Price = 169.99. Try common ARIA role/name combinations.
    price_value = "169.99"
    price_candidates = [
        ("spinbutton", "Price *"),
        ("spinbutton", "Price"),
        ("textbox", "Price *"),
        ("textbox", "Price"),
    ]
    for role, name in price_candidates:
        try:
            await page.get_by_role(role, name=name).fill(price_value)
            break
        except Exception:
            continue

    # 3) Open Inventory panel to expose Qty and stock controls
    try:
        await page.get_by_role("link", name="Inventory").click()
        try:
            await page.wait_for_load_state("networkidle")
        except Exception:
            await asyncio.sleep(0.5)
    except Exception:
        # fallback to tab role
        try:
            await page.get_by_role("tab", name="Inventory").click()
            try:
                await page.wait_for_load_state("networkidle")
            except Exception:
                await asyncio.sleep(0.5)
        except Exception:
            pass

    # 4) Set Quantity = 42 using several plausible role/name combos
    qty_value = "42"
    qty_candidates = [
        ("spinbutton", "Qty"),
        ("spinbutton", "Quantity"),
        ("textbox", "Qty"),
        ("textbox", "Quantity"),
        ("textbox", "Qty *"),
    ]
    for role, name in qty_candidates:
        try:
            await page.get_by_role(role, name=name).fill(qty_value)
            break
        except Exception:
            continue

    # 5) Mark as In Stock. Try common combobox names and select by label or value.
    in_stock_candidates = [
        ("Is In Stock", "In Stock"),
        ("Is in Stock", "In Stock"),
        ("Stock Availability", "In Stock"),
        ("Stock Availability *", "In Stock"),
        ("Is In Stock", "1"),
    ]
    for comb_name, opt in in_stock_candidates:
        try:
            comb = page.get_by_role("combobox", name=comb_name)
        except Exception:
            continue
        try:
            if opt.isdigit():
                await comb.select_option(value=opt)
            else:
                await comb.select_option(label=opt)
            break
        except Exception:
            continue

    # 6) Set Size -> 34 (if present)
    try:
        await page.get_by_role("combobox", name="Size").select_option(label="34")
    except Exception:
        try:
            await page.get_by_role("combobox", name="size").select_option(label="34")
        except Exception:
            pass

    # 7) Set Color -> Blue (if present)
    try:
        await page.get_by_role("combobox", name="Color").select_option(label="Blue")
    except Exception:
        try:
            await page.get_by_role("combobox", name="color").select_option(label="Blue")
        except Exception:
            pass

    # 8) Save the product. This is expected to navigate away, so do it as the final action.
    try:
        await page.get_by_role("button", name="Save").click()
    except Exception:
        # Fallbacks for alternate save labels
        for alt in ("Save Product", "Save and Continue Edit"):
            try:
                await page.get_by_role("button", name=alt).click()
                break
            except Exception:
                continue

